namespace sv_5b742c2bfdf14a338b39a3a5b25a4e8b;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public record ThemeInfo(ThemeMode Mode, string AccentColor)
{
    public static ThemeInfo Default => new(ThemeMode.Light, "#0d6efd");
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@Theme?.Mode" @onchange="OnModeChanged">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color"
                       class="form-control form-control-color"
                       value="@(Theme?.AccentColor ?? ThemeInfo.Default.AccentColor)"
                       @onchange="OnAccentChanged" />
                <span class="text-muted">@Theme?.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mb-0">
            Current theme: <strong>@Theme?.Mode</strong> &mdash;
            Accent: <span style="color: @Theme?.AccentColor;">&#9632;</span>
            <code>@Theme?.AccentColor</code>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task OnModeChanged(ChangeEventArgs e)
    {
        var mode = Enum.Parse<ThemeMode>((string)e.Value!);
        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo(mode, Theme?.AccentColor ?? ThemeInfo.Default.AccentColor));
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        var color = (string)e.Value!;
        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo(Theme?.Mode ?? ThemeInfo.Default.Mode, color));
    }
}

